document.querySelector("#batch39 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/paranormal-special5.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف خمنوا معي : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 5\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>خمنوا معي : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 5</h3><p>تعرّف النبذة خمنوا معي كتجربة ألغاز ومنافسة قراءة تدعو المتلقي إلى التفكير، مع صلة بعالم فانتازيا ضمن الأعداد الخاصة المشتركة. هنا لا يقتصر دور ا…</p><small>أحمد خالد توفيق</small></a><a class=\"card\" href=\"summaries/paranormal-special6.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف P.C.R: الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 6\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>P.C.R: الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 6</h3><p>تضع نبذة P.C.R علاء في مواجهة لغز تتصل عناصره بتفشٍّ مرضي وأسئلة وراثية، داخل عالم سفاري وأعداده الخاصة المشتركة. المصطلح الطبي في العنوان جزء من…</p><small>أحمد خالد توفيق</small></a><a class=\"card\" href=\"summaries/paranormal-special8.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف تلك المدينة: الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 8\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>تلك المدينة: الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 8</h3><p>تقدم النبذة ماجي وهي تحتفظ بأوراق رفعت إسماعيل، فتكون الكتابة المحفوظة إطارا للوصول إلى الحكاية. يضيف هذا الإطار مسافة بين صاحب التجربة ومن يتلقا…</p><small>أحمد خالد توفيق</small></a>");
